"""Independent reference implementation of the exact fused dot product.

Written directly from the spec with Fraction arithmetic and comparison-based
rounding -- deliberately different code path from main.py (which uses scaled
integers). Used only for testing.
"""
from fractions import Fraction

TWO = Fraction(2)


def floor_log2(x):
    """floor(log2(x)) for positive Fraction x."""
    n, d = x.numerator, x.denominator
    L = n.bit_length() - d.bit_length()
    if L >= 0:
        if n < (d << L):
            L -= 1
    else:
        if (n << (-L)) < d:
            L -= 1
    return L


def ref_fused_dot(ebits, fbits, mode, pairs):
    bias = (1 << (ebits - 1)) - 1
    F = 1 << fbits
    Eall = (1 << ebits) - 1
    emin = 1 - bias
    emax = Eall - 1 - bias
    w = 1 + ebits + fbits
    mask = (1 << w) - 1

    def decode(h):
        v = int(h, 16) & mask
        s = (v >> (ebits + fbits)) & 1
        e = (v >> fbits) & Eall
        f = v & (F - 1)
        if e == Eall:
            if f == 0:
                return ("inf", s)
            return ("nan", s, ((f >> (fbits - 1)) & 1) == 0)
        if e == 0:
            if f == 0:
                return ("zero", s)
            return ("fin", s, Fraction(f) * TWO ** (emin - fbits))
        return ("fin", s, Fraction(F + f) * TWO ** (e - bias - fbits))

    any_nan = False
    invalid = False
    inf_signs = set()
    products = []  # (sign, magnitude Fraction) for finite pairs
    for pa, pb in pairs:
        a = decode(pa)
        b = decode(pb)
        if a[0] == "nan" or b[0] == "nan":
            any_nan = True
            if (a[0] == "nan" and a[2]) or (b[0] == "nan" and b[2]):
                invalid = True
            continue
        if a[0] == "inf" or b[0] == "inf":
            if a[0] == "zero" or b[0] == "zero":
                invalid = True
            else:
                inf_signs.add(a[1] ^ b[1])
            continue
        s = a[1] ^ b[1]
        mag = (a[2] if a[0] == "fin" else Fraction(0)) * \
              (b[2] if b[0] == "fin" else Fraction(0))
        products.append((s, mag))

    if len(inf_signs) > 1:
        invalid = True
    if any_nan or invalid:
        return ((Eall << fbits) | (1 << (fbits - 1)),
                frozenset(["invalid"]) if invalid else frozenset())
    if inf_signs:
        s = next(iter(inf_signs))
        return ((s << (w - 1)) | (Eall << fbits)), frozenset()

    total = sum(((-m if s else m) for s, m in products), Fraction(0))
    if total == 0:
        neg = (mode == "RDN") or (len(products) > 0 and
                                  all(s == 1 and m == 0 for s, m in products))
        return ((1 << (w - 1)) if neg else 0), frozenset()

    sign = 1 if total < 0 else 0
    x = -total if sign else total
    L = floor_log2(x)
    qexp = max(emin - fbits, L - fbits)
    q = TWO ** qexp
    r = x / q
    fl = r.numerator // r.denominator
    rem = r - fl
    half = Fraction(1, 2)
    if mode == "RTZ":
        m = fl
    elif mode == "RUP":
        m = fl + 1 if (rem and sign == 0) else fl
    elif mode == "RDN":
        m = fl + 1 if (rem and sign == 1) else fl
    elif mode == "RNA":
        m = fl + 1 if rem >= half else fl
    else:  # RNE
        m = fl + 1 if (rem > half or (rem == half and fl % 2 == 1)) else fl
    y = m * q
    inexact = (y != x)

    if y >= TWO ** (emax + 1):
        if (mode in ("RNE", "RNA") or (mode == "RUP" and sign == 0)
                or (mode == "RDN" and sign == 1)):
            bits = Eall << fbits
        else:
            bits = ((Eall - 1) << fbits) | (F - 1)
        return (bits | (sign << (w - 1))), frozenset(["overflow", "inexact"])

    flags = set()
    if inexact:
        flags.add("inexact")
        if y < TWO ** emin:
            flags.add("underflow")
    if m == 0:
        return (sign << (w - 1)), frozenset(flags)

    if y >= TWO ** emin:
        e = floor_log2(y)
        sig = y / (TWO ** (e - fbits))
        assert sig.denominator == 1, "normal significand not integral"
        bits = ((e + bias) << fbits) | (sig.numerator - F)
    else:
        fr = y / (TWO ** (emin - fbits))
        assert fr.denominator == 1, "subnormal fraction not integral"
        bits = fr.numerator
    return (bits | (sign << (w - 1))), frozenset(flags)
